// v3cb01_task_machinery / ex1 - building tasks by hand, with no async keyword.

namespace CSharpDojo.V3CB01_TaskMachinery;

public static class Promise
{
    /// <summary>
    /// A pending task plus the button that completes it. This is the
    /// promise/future split that <c>AsyncTaskMethodBuilder</c> uses internally.
    /// </summary>
    public static (Task<T> Task, Action<T> Complete) Deferred<T>()
    {
        // RunContinuationsAsynchronously: never let the caller of Complete()
        // end up running the awaiter's remaining code on their own thread.
        var source = new TaskCompletionSource<T>(TaskCreationOptions.RunContinuationsAsynchronously);
        return (source.Task, value => source.SetResult(value));
    }

    /// <summary>An already-successful task; no state machine, no allocation of one.</summary>
    public static Task<int> Immediate(int value) => Task.FromResult(value);

    /// <summary>
    /// A task that is already faulted. The failure is *returned*, not thrown:
    /// calling this method never throws.
    /// </summary>
    public static Task<int> Failed(string message) =>
        Task.FromException<int>(new InvalidOperationException(message));

    /// <summary>
    /// A task in the Canceled state - which requires an already-cancelled
    /// token, and is not the same as a task faulted with OperationCanceledException.
    /// </summary>
    public static Task<int> Cancelled(CancellationToken token)
    {
        if (!token.IsCancellationRequested)
        {
            var source = new CancellationTokenSource();
            source.Cancel();
            token = source.Token;
        }

        return Task.FromCanceled<int>(token);
    }
}

