// v3cb01_task_machinery / ex2 - the synchronous prefix, and caching completed tasks.

namespace CSharpDojo.V3CB01_TaskMachinery;

public static class Prefix
{
    // Built once at type initialisation. Handing these out costs nothing.
    private static readonly Task<int>[] Cache =
    [
        Task.FromResult(0),
        Task.FromResult(10),
        Task.FromResult(20),
    ];

    /// <summary>
    /// Everything before the first await runs on the caller's thread, inside
    /// the call itself - so "entered" is in the log before the caller holds
    /// the task.
    /// </summary>
    public static async Task<int> CountAsync(Task<string> body, List<string> log)
    {
        log.Add("entered");
        string text = await body;
        log.Add("resumed");
        return text.Length;
    }

    /// <summary>
    /// Not an async method: it returns a task rather than awaiting one, so the
    /// compiler generates no state machine and the cache hits allocate nothing.
    /// </summary>
    public static Task<int> LookupAsync(int key) => key switch
    {
        >= 0 and <= 2 => Cache[key],
        _ => Task.FromResult(key * 10),
    };

    /// <summary>
    /// True when the call completed without ever suspending - the fast path.
    /// </summary>
    public static bool WasSynchronous(Func<Task> call) => call().IsCompleted;
}

