// v3cb01_task_machinery / ex3 - the awaiter pattern, implemented by hand.

using System.Runtime.CompilerServices;
using System.Runtime.ExceptionServices;

namespace CSharpDojo.V3CB01_TaskMachinery;

public sealed class Later<T>
{
    private readonly object gate = new();
    private Action? continuation;
    private Exception? error;
    private T value = default!;
    private bool ready;

    public bool IsReady
    {
        get { lock (gate) { return ready; } }
    }

    public LaterAwaiter<T> GetAwaiter() => new(this);

    public void Publish(T published) => Complete(published, null);

    public void Fail(Exception failure) => Complete(default!, failure);

    private void Complete(T published, Exception? failure)
    {
        Action? waiting;
        lock (gate)
        {
            if (ready) throw new InvalidOperationException("already published");
            value = published;
            error = failure;
            ready = true;
            waiting = continuation;
            continuation = null;
        }

        waiting?.Invoke();
    }

    internal void Register(Action registered)
    {
        bool runNow;
        lock (gate)
        {
            runNow = ready;
            if (!runNow) continuation = registered;
        }

        if (runNow) registered();
    }

    internal T Read()
    {
        lock (gate)
        {
            // Capture/Throw keeps the original stack trace instead of resetting it.
            if (error is not null) ExceptionDispatchInfo.Capture(error).Throw();
            return value;
        }
    }
}

/// <summary>
/// The three members the compiler looks for, plus INotifyCompletion. No
/// interface on <see cref="Later{T}"/> itself is required: await is duck-typed.
/// </summary>
public readonly struct LaterAwaiter<T> : INotifyCompletion
{
    private readonly Later<T> source;

    public LaterAwaiter(Later<T> source) => this.source = source;

    public bool IsCompleted => source.IsReady;

    public void OnCompleted(Action continuation) => source.Register(continuation);

    public T GetResult() => source.Read();
}

public static class Awaiting
{
    public static async Task<int> Consume(Later<int> later) => await later + 1;
}

