// v3cb01_task_machinery / ex4 - Task.Yield and the always-vs-sometimes suspension.

namespace CSharpDojo.V3CB01_TaskMachinery;

public static class Yielding
{
    /// <summary>
    /// Task.Yield()'s awaiter reports IsCompleted == false unconditionally, so
    /// the state machine always takes the suspend branch and returns to the
    /// caller with only "before" logged.
    /// </summary>
    public static async Task<int> AlwaysAsync(List<string> log)
    {
        log.Add("before");
        await Task.Yield();
        log.Add("after");
        return log.Count;
    }

    /// <summary>
    /// Ordinary async method: with an already-completed input there is no
    /// suspension, so the returned task is complete before the caller sees it.
    /// </summary>
    public static async Task<int> SometimesAsync(Task<int> work, List<string> log)
    {
        log.Add("before");
        int value = await work;
        log.Add("after");
        return value;
    }

    public static bool NeverCompletesSynchronously(Func<Task> call) => !call().IsCompleted;
}

