// v3cb01_task_machinery / ex5 - continuation hijacking and RunContinuationsAsynchronously.

namespace CSharpDojo.V3CB01_TaskMachinery;

public static class Hijack
{
    /// <summary>
    /// The dangerous default: SetResult invokes waiting continuations inline,
    /// on the completing thread, before it returns.
    /// </summary>
    public static TaskCompletionSource<int> Inline() => new();

    /// <summary>
    /// The version you almost always want: continuations are queued to the
    /// thread pool, so SetResult returns immediately.
    /// </summary>
    public static TaskCompletionSource<int> Detached() =>
        new(TaskCreationOptions.RunContinuationsAsynchronously);

    public static int CompleteAndReport(TaskCompletionSource<int> source, List<string> log)
    {
        log.Add("completing");
        source.SetResult(1);
        log.Add("completed");
        return log.Count;
    }

    /// <summary>
    /// A signal whose Signal() caller can never be hijacked into running the
    /// awaiting code.
    /// </summary>
    public static (Task Task, Action Signal) SafeSignalAsync(List<string> log)
    {
        var source = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        return (source.Task, () =>
        {
            log.Add("signalled");
            source.TrySetResult();
        });
    }
}

