// v3cb01_task_machinery / ex6 - ExecutionContext flow and AsyncLocal.

namespace CSharpDojo.V3CB01_TaskMachinery;

public static class Ambient
{
    private static readonly AsyncLocal<string?> Correlation = new();

    public static void SetCorrelation(string value) => Correlation.Value = value;

    /// <summary>
    /// ExecutionContext is captured at the suspension and restored at the
    /// resumption, so the value survives the await unchanged.
    /// </summary>
    public static async Task<string> ReadAsync(Task gate)
    {
        string? before = Correlation.Value;
        await gate;
        string? after = Correlation.Value;
        return $"{before}|{after}";
    }

    /// <summary>Task.Run captures the current context, so the pool work sees it.</summary>
    public static Task<string?> ReadFromPoolAsync() => Task.Run(() => Correlation.Value);

    /// <summary>
    /// The write happens in a copy of the context owned by the pool work.
    /// Nothing flows back up, so the caller still sees its own value.
    /// </summary>
    public static async Task<string?> MutateInsideAsync(string value)
    {
        await Task.Run(() => Correlation.Value = value);
        return Correlation.Value;
    }

    /// <summary>
    /// With flow suppressed the work item gets no context at all, so the
    /// AsyncLocal reads back as null.
    /// </summary>
    public static async Task<string?> SuppressedAsync()
    {
        using (ExecutionContext.SuppressFlow())
        {
            return await Task.Run(() => Correlation.Value);
        }
    }
}

