// v3cb01_task_machinery / ex7 - Task.Run, nesting, and Unwrap.

namespace CSharpDojo.V3CB01_TaskMachinery;

public static class Offload
{
    /// <summary>The legitimate use: push CPU-bound work off the current thread.</summary>
    public static Task<int> ComputeAsync(int[] values) => Task.Run(() => values.Sum());

    /// <summary>
    /// What you get when the Func&lt;Task&lt;int&gt;&gt; binds to the plain
    /// Func&lt;TResult&gt; overload: a task whose result is a task.
    /// </summary>
    public static Task<Task<int>> Wrapped(Func<Task<int>> work) => Task.Run<Task<int>>(() => work());

    /// <summary>Unwrap flattens the proxy, propagating result, failure and cancellation.</summary>
    public static Task<int> Unwrapped(Func<Task<int>> work) => Wrapped(work).Unwrap();

    /// <summary>
    /// No Task.Run at all. Work that is already asynchronous gains nothing
    /// from a pool hop - on a server it costs a queue operation per call.
    /// </summary>
    public static Task<int> Direct(Func<Task<int>> work) => work();

    public static bool SameThread(Func<Task<int>> work)
    {
        int caller = Environment.CurrentManagedThreadId;
        int observed = caller;
        Task<int> task = Direct(() =>
        {
            observed = Environment.CurrentManagedThreadId;
            return work();
        });
        task.GetAwaiter().GetResult();
        return observed == caller;
    }
}

