// v3cb01_task_machinery / review1 - predicting and producing an exact order.

namespace CSharpDojo.V3CB01_TaskMachinery;

public static class Trace
{
    /// <summary>
    /// Everything before the await runs inside the call; everything after it
    /// runs when the gate completes, which is after the caller has regained
    /// control and written its own entry.
    /// </summary>
    public static async Task RunAsync(TaskCompletionSource<int> gate, List<string> log)
    {
        log.Add("start");
        log.Add("sync-work");
        await gate.Task;
        log.Add("resumed");
        log.Add("done");
    }

    public static async Task<string> OrderOf(Func<List<string>, Task> body)
    {
        List<string> log = [];
        await body(log);
        return string.Join(",", log);
    }

    /// <summary>
    /// Reports what it observes rather than assuming: whether the continuation
    /// ran depends on how the caller built the source.
    /// </summary>
    public static bool ContinuationRanInline(TaskCompletionSource<int> gate)
    {
        int observed = -1;
        Task recorded = gate.Task.ContinueWith(
            _ => observed = Environment.CurrentManagedThreadId,
            CancellationToken.None,
            TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default);

        int completer = Environment.CurrentManagedThreadId;
        gate.TrySetResult(1);
        recorded.GetAwaiter().GetResult();
        return observed == completer;
    }

    /// <summary>
    /// Every await sees IsCompleted == true, so no branch ever returns early
    /// and the whole body runs inside the call.
    /// </summary>
    public static async Task NeverSuspends(Task<int> completed, List<string> log)
    {
        log.Add("start");
        int value = await completed;
        log.Add($"got {value}");
        log.Add("done");
    }
}

