// v3cb02_valuetask_pooling / ex1 - the cache-first ValueTask shape.

namespace CSharpDojo.V3CB02_ValueTaskPooling;

public sealed class Store
{
    private readonly Dictionary<string, int> cache = [];
    private readonly Func<string, Task<int>> loader;

    public Store(Func<string, Task<int>> loader) => this.loader = loader;

    public int LoadCount { get; private set; }

    /// <summary>
    /// Deliberately not async: on a hit this allocates nothing at all, and the
    /// caller can see IsCompletedSuccessfully before awaiting.
    /// </summary>
    public ValueTask<int> GetAsync(string key)
    {
        if (cache.TryGetValue(key, out int hit)) return new ValueTask<int>(hit);
        return new ValueTask<int>(LoadCoreAsync(key));
    }

    /// <summary>The slow path: allocates a task, exactly as Task&lt;int&gt; would have.</summary>
    private async Task<int> LoadCoreAsync(string key)
    {
        LoadCount++;
        int value = await loader(key).ConfigureAwait(false);
        cache[key] = value;      // only successful loads are cached
        return value;
    }

    public bool TryPeek(string key, out int value) => cache.TryGetValue(key, out value);
}

