namespace CSharpDojo.V3CB02_ValueTaskPooling;

public static class Once
{
    /// <summary>
    /// Broken on purpose. Legal C#, illegal by the ValueTask contract: against
    /// a pooled IValueTaskSource the second await asks about an operation that
    /// has already been recycled.
    /// </summary>
    public static async ValueTask<int> SumTwiceWrong(ValueTask<int> value) =>
        await value + await value;

    /// <summary>One consumption; the int is reused, not the ValueTask.</summary>
    public static async ValueTask<int> SumTwiceRight(ValueTask<int> value)
    {
        int result = await value;
        return result + result;
    }

    /// <summary>Preserve() returns a Task-backed value that is safe to await repeatedly.</summary>
    public static ValueTask<int> Materialize(ValueTask<int> value) => value.Preserve();

    /// <summary>AsTask() consumes the original and yields a full Task for composition.</summary>
    public static Task<int> SafeSnapshot(ValueTask<int> value) => value.AsTask();

    /// <summary>Status inspection is allowed and does not consume the value.</summary>
    public static string DescribeState(ValueTask<int> value) => value switch
    {
        { IsCompletedSuccessfully: true } => "sync",
        { IsCanceled: true } => "cancelled",
        { IsFaulted: true } => "faulted",
        _ => "pending",
    };
}

