// v3cb02_valuetask_pooling / ex3 - combining value tasks without WhenAll.

namespace CSharpDojo.V3CB02_ValueTaskPooling;

public static class Combine
{
    /// <summary>
    /// Harvest the already-completed ones for free; allocate only for the
    /// stragglers. An all-complete input touches no heap at all.
    /// </summary>
    public static ValueTask<int> SumAsync(ValueTask<int>[] items)
    {
        int total = 0;
        List<Task<int>>? pending = null;

        foreach (ValueTask<int> item in items)
        {
            // IsCompletedSuccessfully, not IsCompleted: a faulted value would
            // throw from .Result and turn this into an unintended fail-fast.
            if (item.IsCompletedSuccessfully) total += item.Result;
            else (pending ??= []).Add(item.AsTask());
        }

        if (pending is null) return new ValueTask<int>(total);
        return new ValueTask<int>(FinishAsync(pending, total));
    }

    private static async Task<int> FinishAsync(List<Task<int>> pending, int total)
    {
        int[] rest = await Task.WhenAll(pending).ConfigureAwait(false);
        return total + rest.Sum();
    }

    public static int CompletedCount(ValueTask<int>[] items)
    {
        int count = 0;
        foreach (ValueTask<int> item in items)
            if (item.IsCompletedSuccessfully) count++;
        return count;
    }

    /// <summary>Each input is converted exactly once; the loser keeps running.</summary>
    public static async Task<int> FirstResultAsync(ValueTask<int> a, ValueTask<int> b)
    {
        Task<int> first = a.AsTask();
        Task<int> second = b.AsTask();
        Task<int> winner = await Task.WhenAny(first, second).ConfigureAwait(false);
        return await winner.ConfigureAwait(false);
    }
}

