// v3cb02_valuetask_pooling / ex4 - a reusable promise over ManualResetValueTaskSourceCore.

using System.Threading.Tasks.Sources;

namespace CSharpDojo.V3CB02_ValueTaskPooling;

public sealed class ReusableOperation : IValueTaskSource<int>
{
    // Mutable struct field: must NOT be readonly, or every mutating call would
    // operate on a defensive copy and silently do nothing.
    private ManualResetValueTaskSourceCore<int> core = new()
    {
        RunContinuationsAsynchronously = true,
    };

    private bool inFlight;

    public short Version => core.Version;

    public int Completions { get; private set; }

    /// <summary>Hands out a ValueTask identified by the current version token.</summary>
    public ValueTask<int> Start()
    {
        if (inFlight) throw new InvalidOperationException("an operation is already in flight");
        inFlight = true;
        return new ValueTask<int>(this, core.Version);
    }

    public void Complete(int value) => core.SetResult(value);

    public void Fail(Exception error) => core.SetException(error);

    public ValueTaskSourceStatus GetStatus(short token) => core.GetStatus(token);

    public void OnCompleted(Action<object?> continuation, object? state, short token,
        ValueTaskSourceOnCompletedFlags flags) =>
        core.OnCompleted(continuation, state, token, flags);

    /// <summary>
    /// Consuming the result resets the core - bumping Version, invalidating any
    /// stale ValueTask, and freeing the instance for the next operation. The
    /// finally runs even when the operation failed.
    /// </summary>
    public int GetResult(short token)
    {
        try
        {
            return core.GetResult(token);
        }
        finally
        {
            Completions++;
            inFlight = false;
            core.Reset();
        }
    }
}

