// v3cb02_valuetask_pooling / ex5 - faulted and cancelled value tasks.

namespace CSharpDojo.V3CB02_ValueTaskPooling;

public static class States
{
    /// <summary>Returned faulted; calling this method never throws.</summary>
    public static ValueTask<int> Failed(string message) =>
        ValueTask.FromException<int>(new InvalidOperationException(message));

    /// <summary>
    /// The genuine cancelled state, which requires an already-cancelled token -
    /// not the same as faulting with an OperationCanceledException.
    /// </summary>
    public static ValueTask<int> Cancelled(CancellationToken token)
    {
        if (!token.IsCancellationRequested)
        {
            var source = new CancellationTokenSource();
            source.Cancel();
            token = source.Token;
        }

        return ValueTask.FromCanceled<int>(token);
    }

    /// <summary>
    /// Status inspection does not consume. Naming the exception type needs the
    /// underlying task, so Preserve() first and leave the caller's copy usable.
    /// </summary>
    public static string Classify(ValueTask<int> value)
    {
        if (value.IsCanceled) return "cancelled";
        if (value.IsCompletedSuccessfully) return "ok";
        if (!value.IsFaulted) return "pending";

        Exception? cause = value.Preserve().AsTask().Exception?.InnerException;
        return $"faulted:{cause?.GetType().Name ?? nameof(Exception)}";
    }

    /// <summary>
    /// Cancellation is not a failure: it is rethrown, while real faults fall
    /// back. Clause order matters - a bare catch first would swallow it.
    /// </summary>
    public static async ValueTask<int> ReadOrDefaultAsync(ValueTask<int> value, int fallback)
    {
        try
        {
            return await value.ConfigureAwait(false);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception)
        {
            return fallback;
        }
    }

    /// <summary>Non-async wrapper: bad arguments throw at the call site.</summary>
    public static ValueTask<int> EagerGuard(int[]? values)
    {
        ArgumentNullException.ThrowIfNull(values);
        return new ValueTask<int>(values.Sum());
    }
}

