namespace CSharpDojo.V3CB02_ValueTaskPooling;

public sealed class BufferedSequence : IAsyncEnumerable<int>
{
    private readonly int[][] pages;

    public BufferedSequence(int[][] pages) => this.pages = pages;

    public int SyncMoves { get; private set; }

    public IAsyncEnumerator<int> GetAsyncEnumerator(CancellationToken token = default) =>
        new Enumerator(this);

    public sealed class Enumerator : IAsyncEnumerator<int>
    {
        private readonly BufferedSequence owner;
        private int[] buffer = [];
        private int pageIndex = -1;
        private int index = -1;

        internal Enumerator(BufferedSequence owner) => this.owner = owner;

        public int Current => buffer[index];

        /// <summary>
        /// Within a page the answer is already in hand, so the ValueTask is
        /// completed synchronously and costs nothing. Only a page boundary
        /// takes the allocating path.
        /// </summary>
        public ValueTask<bool> MoveNextAsync()
        {
            if (index + 1 < buffer.Length)
            {
                index++;
                owner.SyncMoves++;
                return new ValueTask<bool>(true);
            }

            return new ValueTask<bool>(AdvancePageAsync());
        }

        private async Task<bool> AdvancePageAsync()
        {
            while (pageIndex + 1 < owner.pages.Length)
            {
                await Task.Yield();          // a real suspension at the boundary
                pageIndex++;
                buffer = owner.pages[pageIndex];
                index = 0;
                if (buffer.Length > 0) return true;
            }

            return false;                     // exhausted: return false, never throw
        }

        /// <summary>Nothing to release, so hand back an already-completed ValueTask.</summary>
        public ValueTask DisposeAsync() => default;
    }
}

