using System.Runtime.CompilerServices;

namespace CSharpDojo.V3CB02_ValueTaskPooling;

public static class Pooled
{
    /// <summary>
    /// Same semantics as PlainAsync; the builder recycles the boxed state
    /// machine when this method suspends.
    /// </summary>
    [AsyncMethodBuilder(typeof(PoolingAsyncValueTaskMethodBuilder<>))]
    public static async ValueTask<int> SumAsync(Task<int>[] work)
    {
        int total = 0;
        foreach (Task<int> item in work) total += await item.ConfigureAwait(false);
        return total;
    }

    public static async ValueTask<int> PlainAsync(Task<int>[] work)
    {
        int total = 0;
        foreach (Task<int> item in work) total += await item.ConfigureAwait(false);
        return total;
    }

    /// <summary>
    /// No async keyword, so no builder and no state machine at all when every
    /// input is already done - the complementary optimisation to pooling.
    /// </summary>
    public static ValueTask<int> NoBuilderAsync(Task<int>[] work)
    {
        int total = 0;
        foreach (Task<int> item in work)
        {
            if (!item.IsCompletedSuccessfully) return PlainAsync(work);
            total += item.Result;
        }

        return new ValueTask<int>(total);
    }

    /// <summary>
    /// Pooling helps the suspending path; skipping the builder helps the
    /// synchronous one. Only the third avoids the machinery when nothing waits.
    /// </summary>
    public static string Describe() => "NoBuilderAsync";
}

