// v3cb02_valuetask_pooling / challenge - a buffered reader with a reusable promise.

using System.Threading.Tasks.Sources;

namespace CSharpDojo.V3CB02_ValueTaskPooling;

public sealed class PullReader : IValueTaskSource<int>
{
    private ManualResetValueTaskSourceCore<int> core = new()
    {
        RunContinuationsAsynchronously = true,
    };

    private readonly int[] source;
    private readonly int chunkSize;
    private int released;              // how far into source has been made available
    private int bufferStart;           // window of source currently readable
    private int available;
    private bool pending;
    private Memory<int> destination;   // where a pending read wants its data

    public PullReader(int[] source, int chunkSize)
    {
        this.source = source;
        this.chunkSize = chunkSize > 0 ? chunkSize : throw new ArgumentOutOfRangeException(nameof(chunkSize));
    }

    public int SyncReads { get; private set; }

    public int AsyncReads { get; private set; }

    private bool Exhausted => available == 0 && released >= source.Length;

    /// <summary>
    /// Buffered data (and end of source) answer synchronously with no promise
    /// object at all. Only a genuine wait hands out (this, version).
    /// </summary>
    public ValueTask<int> ReadAsync(Memory<int> target)
    {
        if (available > 0 || Exhausted)
        {
            SyncReads++;
            return new ValueTask<int>(CopyOut(target));
        }

        if (pending) throw new InvalidOperationException("a read is already in flight");

        pending = true;
        destination = target;
        AsyncReads++;
        return new ValueTask<int>(this, core.Version);
    }

    /// <summary>Makes the next chunk readable, completing a waiting read if there is one.</summary>
    public void Release()
    {
        if (released >= source.Length)
        {
            // Nothing left: an outstanding read must still be told "0", or a
            // consumer loop would hang at end of source.
            if (pending) CompletePending();
            return;
        }

        bufferStart = released;
        available = Math.Min(chunkSize, source.Length - released);
        released += available;

        if (pending) CompletePending();
    }

    private void CompletePending()
    {
        int count = CopyOut(destination);
        destination = default;
        core.SetResult(count);
    }

    private int CopyOut(Memory<int> target)
    {
        int count = Math.Min(target.Length, available);
        source.AsSpan(bufferStart, count).CopyTo(target.Span);
        bufferStart += count;
        available -= count;
        return count;
    }

    public ValueTaskSourceStatus GetStatus(short token) => core.GetStatus(token);

    public void OnCompleted(Action<object?> continuation, object? state, short token,
        ValueTaskSourceOnCompletedFlags flags) =>
        core.OnCompleted(continuation, state, token, flags);

    /// <summary>Reset in a finally so a failed read does not retire the instance.</summary>
    public int GetResult(short token)
    {
        try
        {
            return core.GetResult(token);
        }
        finally
        {
            pending = false;
            core.Reset();
        }
    }
}

