namespace CSharpDojo.V3CB03_Cancellation;

public static class Cooperative
{
    public static int Processed { get; private set; }

    /// <summary>
    /// The check goes before the work, so an already-cancelled call does none
    /// at all. ThrowIfCancellationRequested attaches the right token, which is
    /// what makes the resulting task end Canceled rather than Faulted.
    /// </summary>
    public static Task<int> ProcessAsync(IReadOnlyList<int> items, CancellationToken token)
    {
        int total = 0;
        foreach (int item in items)
        {
            token.ThrowIfCancellationRequested();
            total += item;
            Processed++;
        }

        return Task.FromResult(total);
    }

    /// <summary>
    /// The other contract: partial progress is the answer, so poll and break
    /// rather than throw. Note this completes normally - the caller is not
    /// told a cancellation happened, only how far it got.
    /// </summary>
    public static int CountUntilCancelled(IReadOnlyList<int> items, CancellationToken token)
    {
        int handled = 0;
        foreach (int item in items)
        {
            if (token.IsCancellationRequested) break;
            handled++;
        }

        return handled;
    }

    /// <summary>
    /// False only for CancellationToken.None and default - the escape hatch a
    /// hot path uses to skip registration entirely.
    /// </summary>
    public static bool IsPointless(CancellationToken token) => !token.CanBeCanceled;
}

