namespace CSharpDojo.V3CB03_Cancellation;

public static class Linked
{
    private static int registered;

    /// <summary>
    /// The budget is linked with the caller and the *linked* token goes into
    /// the work, so the work itself stops rather than merely being abandoned.
    /// Both sources are disposed on every path.
    /// </summary>
    public static async Task<int> RunAsync(
        Func<CancellationToken, Task<int>> work,
        TimeSpan limit,
        TimeProvider time,
        CancellationToken caller)
    {
        using var budget = new CancellationTokenSource(limit, time);
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(caller, budget.Token);
        return await work(linked.Token).ConfigureAwait(false);
    }

    public static int Registrations(CancellationToken token) => Volatile.Read(ref registered);

    /// <summary>A static lambda captures nothing, so the delegate is cached.</summary>
    public static IDisposable Watch(CancellationToken token)
    {
        Interlocked.Increment(ref registered);
        return new Unhook(token.Register(static () => { }));
    }

    /// <summary>Wrong on purpose: each child stays attached to the parent for ever.</summary>
    public static int LeakDemo(CancellationToken longLived, int count)
    {
        for (int i = 0; i < count; i++)
        {
            CancellationTokenSource child = CancellationTokenSource.CreateLinkedTokenSource(longLived);
            Interlocked.Increment(ref registered);
            _ = child.Token;
        }

        return count;
    }

    public static int NoLeak(CancellationToken longLived, int count)
    {
        for (int i = 0; i < count; i++)
        {
            using CancellationTokenSource child =
                CancellationTokenSource.CreateLinkedTokenSource(longLived);
            _ = child.Token;
        }

        return count;
    }

    private sealed class Unhook(CancellationTokenRegistration registration) : IDisposable
    {
        public void Dispose()
        {
            registration.Dispose();
            Interlocked.Decrement(ref registered);
        }
    }
}

