// v3cb03_cancellation_timeouts / ex4 - Register, disposal, and the immediate-callback rule.

namespace CSharpDojo.V3CB03_Cancellation;

public static class Bridge
{
    private static int live;

    public static int Registered => Volatile.Read(ref live);

    /// <summary>
    /// Cancels the *wait*, not the work: whoever was going to complete the
    /// source still can, and still will. The registration is released on both
    /// paths.
    /// </summary>
    public static async Task<int> WaitAsync(TaskCompletionSource<int> source, CancellationToken token)
    {
        Interlocked.Increment(ref live);
        CancellationTokenRegistration registration = token.Register(
            static state => ((TaskCompletionSource<int>)state!).TrySetCanceled(), source);

        try
        {
            return await source.Task.ConfigureAwait(false);
        }
        finally
        {
            registration.Dispose();
            Interlocked.Decrement(ref live);
        }
    }

    /// <summary>
    /// Registering on an already-cancelled token invokes the callback
    /// synchronously, on this thread, before Register returns.
    /// </summary>
    public static bool RunsImmediately(CancellationToken cancelled, List<string> log)
    {
        using CancellationTokenRegistration registration =
            cancelled.Register(state => ((List<string>)state!).Add("fired"), log);

        return log.Contains("fired");
    }

    /// <summary>The state-taking overload with a static lambda allocates no closure.</summary>
    public static CancellationTokenRegistration NoClosure(
        TaskCompletionSource<int> source, CancellationToken token) =>
        token.Register(static state => ((TaskCompletionSource<int>)state!).TrySetCanceled(), source);
}

