namespace CSharpDojo.V3CB03_Cancellation;

public static class Abandon
{
    public static int Abandoned { get; private set; }

    /// <summary>
    /// Stops the wait. The work carries on holding whatever it holds - the
    /// name says so deliberately, because the caller's next decision depends
    /// on knowing it.
    /// </summary>
    public static async Task<int> WaitOrAbandonAsync(Task<int> work, CancellationToken token)
    {
        try
        {
            return await work.WaitAsync(token).ConfigureAwait(false);
        }
        catch (OperationCanceledException)
        {
            Abandoned++;
            ObserveFailures(work);
            throw;
        }
    }

