    /// An orphaned task that later faults would otherwise raise
    /// TaskScheduler.UnobservedTaskException and vanish.
    /// </summary>
    public static void ObserveFailures(Task<int> work) =>
        _ = work.ContinueWith(
            static t => _ = t.Exception,
            CancellationToken.None,
            TaskContinuationOptions.OnlyOnFaulted | TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default);

    /// <summary>A snapshot, and honest about being one.</summary>
    public static bool StillRunning(Task<int> work) => !work.IsCompleted;
}

