// v3cb03_cancellation_timeouts / ex7 - retry with backoff, driven by an injected clock.

namespace CSharpDojo.V3CB03_Cancellation;

public static class Retry
{
    public static List<TimeSpan> Delays { get; } = [];

    public static int Attempts { get; private set; }

    /// <summary>Pure, so it can be tested and reasoned about on its own.</summary>
    public static TimeSpan NextDelay(int attempt) => TimeSpan.FromSeconds(1 << attempt);

    /// <summary>
    /// The delay takes the TimeProvider, so a fake clock drives the whole
    /// schedule - and takes the token, so a cancelled caller stops waiting.
    /// </summary>
    public static async Task<int> RunAsync(
        Func<int, Task<int>> attempt,
        int maxAttempts,
        TimeProvider time,
        CancellationToken token)
    {
        for (int n = 0; ; n++)
        {
            try
            {
                Attempts++;
                return await attempt(n).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                throw;                       // never retry an abandoned request
            }
            catch when (n + 1 < maxAttempts)
            {
                TimeSpan delay = NextDelay(n);
                Delays.Add(delay);
                await Task.Delay(delay, time, token).ConfigureAwait(false);
            }
        }
    }
}

exercises.hints:
## Hint 1

Three phases, three lines of thinking:

1. A flag that `TryAccept` reads. Once set, nothing new gets in.
2. `Task.WhenAll` over the in-flight set — but bounded, so it cannot wait for
   ever.
3. A report that tells the truth about which of the two happened.

The bound is the interesting part: you want to stop waiting without pretending
the work finished.

## Hint 2

```csharp
Task all = Task.WhenAll(inFlight);
try
{
    await all.WaitAsync(grace, time).ConfigureAwait(false);
    return $"drained: {inFlight.Count}";
}
catch (TimeoutException)
{
    int stuck = inFlight.Count(t => !t.IsCompleted);
    return $"forced: {stuck}";
}
```

`WaitAsync(grace, time)` throws `TimeoutException` on the deadline, which is
exactly the classification you want here — this is not a cancellation, it is
your own budget expiring.

## Hint 3

The rule the last bullet is pointing at is the one people get wrong under
pressure: **cleanup does not use the token that told you to stop.**

```csharp
// wrong: the stopping token is already cancelled, so the flush never happens
await FlushAsync(stoppingToken);

// right: cleanup gets its own budget
using var cleanup = new CancellationTokenSource(grace, time);
await FlushAsync(cleanup.Token);
```

Passing the stopping token into your flush means the flush is cancelled the
instant it starts, and data is lost during an *orderly* shutdown — the one
situation where you had every opportunity to save it.

Left to you: what "forced" should do beyond reporting. Options are to log the
identities of the stuck work, to write them somewhere durable for recovery, or
simply to exit. What you must not do is report success — a shutdown that
silently abandons work while claiming to have drained is how data loss becomes
undiagnosable.

