// v3cb03_cancellation_timeouts / ex8 - stop accepting, drain, then give up honestly.

namespace CSharpDojo.V3CB03_Cancellation;

public sealed class Drain
{
    private readonly object gate = new();
    private readonly List<Task<int>> inFlight = [];
    private bool stopping;

    public int InFlight
    {
        get { lock (gate) { return inFlight.Count(task => !task.IsCompleted); } }
    }

    /// <summary>
    /// Check-and-add must be one step: shutdown beginning between the two
    /// would admit work nobody waits for.
    /// </summary>
    public bool TryAccept(Task<int> work)
    {
        lock (gate)
        {
            if (stopping) return false;
            inFlight.Add(work);
            return true;
        }
    }

    /// <summary>
    /// Phase 1: stop accepting. Phase 2: wait, bounded by a grace budget that
    /// is *ours*, not the caller's stop signal. Phase 3: report the truth.
    /// </summary>
    public async Task<string> ShutdownAsync(TimeSpan grace, TimeProvider time)
    {
        Task<int>[] pending;
        lock (gate)
        {
            stopping = true;
            pending = [.. inFlight];
        }

        try
        {
            await Task.WhenAll(pending).WaitAsync(grace, time).ConfigureAwait(false);
            return $"drained: {pending.Length}";
        }
        catch (TimeoutException)
        {
            int stuck = pending.Count(task => !task.IsCompleted);
            return $"forced: {stuck}";
        }
        catch (Exception)
        {
            // A failed unit of work is not a failed shutdown: we still drained.
            int stuck = pending.Count(task => !task.IsCompleted);
            return stuck == 0 ? $"drained: {pending.Length}" : $"forced: {stuck}";
        }
    }
}

