// v3cb03_cancellation_timeouts / challenge - per-attempt timeout plus an overall deadline.

namespace CSharpDojo.V3CB03_Cancellation;

public static class Deadline
{
    /// <summary>
    /// Three nested budgets: the caller's token, an overall deadline, and a
    /// fresh per-attempt timeout. Classification always asks a *source*
    /// whether it fired - the exception carries the innermost linked token,
    /// which is equal to none of them.
    /// </summary>
    public static async Task<string> RunAsync(
        Func<CancellationToken, Task<int>> attempt,
        TimeSpan perAttempt,
        TimeSpan overall,
        int maxAttempts,
        TimeProvider time,
        CancellationToken caller)
    {
        using var deadline = new CancellationTokenSource(overall, time);
        using var outer = CancellationTokenSource.CreateLinkedTokenSource(caller, deadline.Token);

        Exception? last = null;

        for (int n = 0; n < maxAttempts; n++)
        {
            using var attemptBudget = new CancellationTokenSource(perAttempt, time);
            using var inner = CancellationTokenSource.CreateLinkedTokenSource(
                outer.Token, attemptBudget.Token);

            try
            {
                int value = await attempt(inner.Token).ConfigureAwait(false);
                return $"ok: {value}";
            }
            catch (OperationCanceledException) when (caller.IsCancellationRequested)
            {
                throw;                                  // never our failure to report
            }
            catch (OperationCanceledException) when (deadline.IsCancellationRequested)
            {
                return "deadline";
            }
            catch (OperationCanceledException)
            {
                last = new TimeoutException($"attempt {n} exceeded {perAttempt}");
            }
            catch (Exception ex)
            {
                last = ex;
            }
        }

        // Out of attempts. The deadline may have passed on the final attempt.
        if (deadline.IsCancellationRequested) return "deadline";
        return $"failed: {last?.GetType().Name ?? nameof(Exception)}";
    }
}

