// v3cb03_cancellation_timeouts / review1 - the four cancellation bugs, diagnosed and repaired.

namespace CSharpDojo.V3CB03_Cancellation;

public static class Audit
{
    public static string Diagnose(string symptom) => symptom switch
    {
        "cancelled requests appear as errors" => "catch clause ordering",
        "memory grows under load" => "undisposed linked source",
        "cancellation does nothing" => "token not forwarded",
        "every later call times out" => "CancelAfter on a shared source",
        _ => "unknown",
    };

    /// <summary>Cancellation is rethrown, never reclassified as a failure.</summary>
    public static async Task<string> RepairedCatch(Task<int> work, CancellationToken token)
    {
        try
        {
            return $"ok: {await work.WaitAsync(token).ConfigureAwait(false)}";
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception ex)
        {
            return $"failed: {ex.GetType().Name}";
        }
    }

    /// <summary>Both sources disposed, so no registration outlives the call.</summary>
    public static async Task<int> RepairedLink(
        Func<CancellationToken, Task<int>> work,
        TimeSpan limit,
        TimeProvider time,
        CancellationToken caller)
    {
        using var budget = new CancellationTokenSource(limit, time);
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(caller, budget.Token);
        return await work(linked.Token).ConfigureAwait(false);
    }

    /// <summary>The caller's intent reaches the callee.</summary>
    public static Task<int> RepairedForward(
        Func<int, CancellationToken, Task<int>> inner, int id, CancellationToken token) =>
        inner(id, token);

    /// <summary>
    /// A CancellationTokenSource is single-use: CancelAfter on a shared one
    /// poisons it permanently. Operations get their own.
    /// </summary>
    public static CancellationTokenSource RepairedTimeout(TimeSpan limit, TimeProvider time) =>
        new(limit, time);
}

