// v3cb04_async_exceptions / ex1 - where an async method's exception lives.

namespace CSharpDojo.V3CB04_AsyncExceptions;

public static class Placement
{
    /// <summary>
    /// Async, so the ArgumentException is captured onto the returned task -
    /// calling this never throws, however wrong the arguments are.
    /// </summary>
    public static async Task<int> CapturedAsync(string? name, Task<int> work)
    {
        ArgumentException.ThrowIfNullOrEmpty(name);
        return name.Length + await work.ConfigureAwait(false);
    }

    /// <summary>Not async: the caller's mistake surfaces at the caller's line.</summary>
    public static Task<int> Eager(string? name, Task<int> work)
    {
        ArgumentException.ThrowIfNullOrEmpty(name);
        return EagerCoreAsync(name, work);
    }

    private static async Task<int> EagerCoreAsync(string name, Task<int> work) =>
        name.Length + await work.ConfigureAwait(false);

    /// <summary>Distinguishes the two moments a failure can appear.</summary>
    public static string Observe(Func<Task<int>> call)
    {
        Task<int> task;
        try
        {
            task = call();
        }
        catch (Exception ex)
        {
            return $"threw:{ex.GetType().Name}";
        }

        if (task.IsFaulted) return $"faulted:{task.Exception!.InnerException!.GetType().Name}";
        return "pending";
    }
}

