// v3cb04_async_exceptions / ex3 - every failure, in list order.

namespace CSharpDojo.V3CB04_AsyncExceptions;

public static class Batch
{
    public static async Task<string> RunAsync(IReadOnlyList<Task<int>> work)
    {
        try
        {
            int[] results = await Task.WhenAll(work).ConfigureAwait(false);
            return $"ok: {results.Sum()}";
        }
        catch (OperationCanceledException)
        {
            throw;                            // abandoned, not failed
        }
        catch
        {
            // The thrown exception is only one of them. The tasks know all of
            // them, and know them in list order.
            string names = string.Join(",", work
                .Where(task => task.IsFaulted)
                .Select(task => task.Exception!.InnerException!.GetType().Name));

            return $"failed: {names}";
        }
    }

    /// <summary>
    /// The same failures from the WhenAll task itself - flattened, and in
    /// completion order rather than list order.
    /// </summary>
    public static string FromWhenAll(Task all) =>
        all.Exception is null
            ? string.Empty
            : string.Join(",", all.Exception.Flatten().InnerExceptions
                .Select(error => error.GetType().Name));

    /// <summary>
    /// IsCompletedSuccessfully, not "not faulted": a cancelled task is neither
    /// a success nor a fault, and its Exception is null.
    /// </summary>
    public static int SucceededCount(IReadOnlyList<Task<int>> work) =>
        work.Count(task => task.IsCompletedSuccessfully);
}

