// v3cb04_async_exceptions / ex4 - flattening, depth, and partitioning aggregates.

namespace CSharpDojo.V3CB04_AsyncExceptions;

public static class Aggregates
{
    /// <summary>Two levels, three leaves - the shape composition produces.</summary>
    public static AggregateException Nested() =>
        new(
            new AggregateException(new IOException("io"), new TimeoutException("slow")),
            new InvalidOperationException("state"));

    /// <summary>Flatten dissolves every nested aggregate into its leaves.</summary>
    public static string LeafNames(AggregateException error) =>
        string.Join(",", error.Flatten().InnerExceptions
            .Select(leaf => leaf.GetType().Name)
            .OrderBy(name => name, StringComparer.Ordinal));

    /// <summary>The one thing Flatten cannot tell you afterwards.</summary>
    public static int Depth(AggregateException error) =>
        1 + error.InnerExceptions
            .OfType<AggregateException>()
            .Select(Depth)
            .DefaultIfEmpty(0)
            .Max();

    /// <summary>Classification without control flow: no exception is thrown here.</summary>
    public static (int Handled, int Rethrown) Partition(
        AggregateException error, Func<Exception, bool> handled)
    {
        int yes = 0, no = 0;
        foreach (Exception leaf in error.Flatten().InnerExceptions)
        {
            if (handled(leaf)) yes++;
            else no++;
        }

        return (yes, no);
    }

    /// <summary>
    /// Flatten before Handle: the predicate is called with this aggregate's
    /// direct inner exceptions, which for a nested one means an aggregate.
    /// Note Handle throws a *new* AggregateException of the unhandled leaves.
    /// </summary>
    public static void HandleOrThrow(AggregateException error, Func<Exception, bool> handled) =>
        error.Flatten().Handle(leaf => handled(leaf));
}

