// v3cb04_async_exceptions / ex5 - Canceled and Faulted are different terminal states.

namespace CSharpDojo.V3CB04_AsyncExceptions;

public static class Terminal
{
    /// <summary>
    /// IsCanceled is tested first because a cancelled task's Exception is null:
    /// reading it before the check looks like a null-reference bug.
    /// </summary>
    public static string Describe(Task task) => task switch
    {
        { IsCanceled: true } => "cancelled",
        { IsFaulted: true } => $"failed:{task.Exception!.InnerException!.GetType().Name}",
        { IsCompletedSuccessfully: true } => "ok",
        _ => "pending",
    };

    public static Task CancelledTask(CancellationToken token)
    {
        if (!token.IsCancellationRequested)
        {
            var source = new CancellationTokenSource();
            source.Cancel();
            token = source.Token;
        }

        return Task.FromCanceled(token);
    }

    /// <summary>
    /// The near-miss: the right exception type, no associated token, so the
    /// task ends Faulted and every downstream policy treats it as an error.
    /// </summary>
    public static Task FaultedWithCancellation() =>
        Task.FromException(new OperationCanceledException("no token attached"));

    public static async Task<string> ClassifyAsync(Task work, CancellationToken token)
    {
        try
        {
            await work.ConfigureAwait(false);
            return "ok";
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            return $"failed:{ex.GetType().Name}";
        }
    }

    /// <summary>
    /// Precise, but brittle under linked sources - there the exception carries
    /// the child token and matches neither parent.
    /// </summary>
    public static bool IsRealCancellation(Exception error, CancellationToken token) =>
        error is OperationCanceledException canceled && canceled.CancellationToken == token;
}

