// v3cb04_async_exceptions / ex6 - rethrowing with the stack trace intact.

using System.Runtime.ExceptionServices;

namespace CSharpDojo.V3CB04_AsyncExceptions;

public static class Rethrow
{
    public static List<string> Log { get; } = [];

    /// <summary>throw; continues the existing propagation: the trace survives.</summary>
    public static async Task Bare(Task work)
    {
        try
        {
            await work.ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            Log.Add(ex.GetType().Name);
            throw;
        }
    }

    /// <summary>throw ex; is a new throw of the same object: the trace is overwritten.</summary>
    public static async Task Reset(Task work)
    {
        try
        {
            await work.ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            Log.Add(ex.GetType().Name);
            throw ex;
        }
    }

    /// <summary>
    /// The only correct way to rethrow an exception that has been stored: the
    /// original trace is captured and re-raised, with the new frames appended.
    /// </summary>
    public static void Captured(Exception error) => ExceptionDispatchInfo.Capture(error).Throw();

    public static bool FramesContain(Exception error, string methodName) =>
        error.StackTrace?.Contains(methodName, StringComparison.Ordinal) ?? false;

    /// <summary>
    /// Collects failures and rethrows at the end - the shape that makes
    /// ExceptionDispatchInfo necessary rather than optional.
    /// </summary>
    public static async Task LastFailureAsync(IReadOnlyList<Task> work)
    {
        Exception? last = null;

        foreach (Task task in work)
        {
            try
            {
                await task.ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                last = ex;
            }
        }

        if (last is not null) ExceptionDispatchInfo.Capture(last).Throw();
    }
}

