namespace CSharpDojo.V3CB04_AsyncExceptions;

public static class Forget
{
    /// <summary>
    /// The counter-example. No task, so no await and no catch: the failure is
    /// posted to the synchronization context or, with none, to the thread pool
    /// where it terminates the process.
    /// </summary>
    public static async void Unsafe(Task work) => await work.ConfigureAwait(false);

    /// <summary>
    /// Returns a task and handles its own failures, so the returned task never
    /// faults and discarding it is genuinely safe.
    /// </summary>
    public static async Task Safe(Task work, List<string> failures)
    {
        try
        {
            await work.ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            failures.Add($"failed:{ex.GetType().Name}");
        }
    }

    /// <summary>The discard makes the intent visible to a reader and to analyzers.</summary>
    public static void Start(Task work, List<string> failures) => _ = Safe(work, failures);

    /// <summary>
    /// The shape an async void event handler must have: the whole body guarded,
    /// so nothing ever reaches the builder.
    /// </summary>
    public static async Task HandlerAsync(Task work, List<string> failures)
    {
        try
        {
            await work.ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            failures.Add($"handled:{ex.GetType().Name}");
        }
    }

    /// <summary>Reading Exception is what marks a faulted task observed.</summary>
    public static bool WasObserved(Task faulted) => faulted.Exception is not null;
}

