namespace CSharpDojo.V3CB04_AsyncExceptions;

public static class Awaiting
{
    /// <summary>
    /// Library code: decline to capture the caller's context, because a
    /// library cannot know whether its caller has one.
    /// </summary>
    public static async Task<int> LibraryAsync(Task<int> work) =>
        await work.ConfigureAwait(false);

    /// <summary>
    /// Wait for completion only. SuppressThrowing marks the failure observed
    /// and does not rethrow - the correct spelling of "I just need this done".
    /// </summary>
    public static async Task<string> WaitOnlyAsync(Task work)
    {
        await work.ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);
        return "done";
    }

    /// <summary>
    /// ForceYielding treats the awaitable as never complete, so the state
    /// machine always suspends and the caller regains control immediately.
    /// </summary>
    public static async Task<int> AlwaysYieldsAsync(Task work, List<string> log)
    {
        log.Add("before");
        await work.ConfigureAwait(ConfigureAwaitOptions.ForceYielding);
        log.Add("after");
        return log.Count;
    }

    public static string Explain(string option) => option switch
    {
        "None" => "do not capture the context",
        "ContinueOnCapturedContext" => "resume on the captured context",
        "ForceYielding" => "always suspend",
        "SuppressThrowing" => "observe the failure, do not rethrow",
        _ => "unknown",
    };

    /// <summary>
    /// ConfigureAwait controls SynchronizationContext capture only.
    /// ExecutionContext - and therefore AsyncLocal - flows regardless.
    /// </summary>
    public static bool FlowsAsyncLocal() => true;
}

