// v3cb04_async_exceptions / challenge - a batch executor that classifies every outcome.

namespace CSharpDojo.V3CB04_AsyncExceptions;

public readonly record struct BatchReport(int Ok, int Cancelled, int Failed, int Total);

public static class Executor
{
    public static async Task<BatchReport> RunAsync(
        IReadOnlyList<Func<CancellationToken, Task<int>>> work,
        IAsyncDisposable resource,
        CancellationToken token)
    {
        // await using: disposal happens on the throwing paths too.
        await using (resource.ConfigureAwait(false))
        {
            Task<int>[] started = [.. work.Select(unit => unit(token))];

            // SuppressThrowing waits for every unit and observes every failure
            // without rethrowing - exactly what a classifier needs.
            await Task.WhenAll(started).ConfigureAwait(ConfigureAwaitOptions.SuppressThrowing);

            int ok = started.Count(task => task.IsCompletedSuccessfully);
            int cancelled = started.Count(task => task.IsCanceled);

            Exception[] failures = [.. started
                .Where(task => task.IsFaulted)
                .Select(task => task.Exception!.InnerException!)];

            // A caller who left outranks everything: their departure is not an
            // error report, however many units also failed.
            token.ThrowIfCancellationRequested();

            if (failures.Length > 0)
            {
                // The original objects, in list order: identity and stack
                // traces both preserved.
                throw new AggregateException($"{failures.Length} of {work.Count} failed", failures);
            }

            return new BatchReport(ok, cancelled, failures.Length, work.Count);
        }
    }
}

