// v3cb05_async_streams / ex1 - a paged async iterator, and its laziness.

namespace CSharpDojo.V3CB05_AsyncStreams;

public static class Pages
{
    public static int Fetches { get; private set; }

    /// <summary>
    /// One await per page, several yields per page: most MoveNextAsync calls
    /// have the answer already, which is why ValueTask&lt;bool&gt; is the return type.
    /// </summary>
    public static async IAsyncEnumerable<int> ItemsAsync(
        Func<int, Task<int[]>> fetchPage, int pageCount)
    {
        for (int page = 0; page < pageCount; page++)
        {
            Fetches++;
            int[] items = await fetchPage(page).ConfigureAwait(false);
            foreach (int item in items) yield return item;
        }
    }

    public static async Task<int> SumAsync(IAsyncEnumerable<int> source)
    {
        int total = 0;
        await foreach (int item in source.ConfigureAwait(false)) total += item;
        return total;
    }

    /// <summary>
    /// Calling an async-iterator method runs none of its body: the state
    /// machine is built, parked at "not started", and returned.
    /// </summary>
    public static bool StartedYet(IAsyncEnumerable<int> source) => Fetches != 0;
}

