using System.Runtime.CompilerServices;

namespace CSharpDojo.V3CB05_AsyncStreams;

public static class Tokens
{
    public static int Produced { get; private set; }

    /// <summary>
    /// The attribute routes the token supplied by WithCancellation into this
    /// parameter, combining it with any token passed at creation time.
    /// </summary>
    public static async IAsyncEnumerable<int> HonouredAsync(
        Func<int, Task<int>> load,
        int count,
        [EnumeratorCancellation] CancellationToken token = default)
    {
        for (int i = 0; i < count; i++)
        {
            token.ThrowIfCancellationRequested();
            Produced++;
            yield return await load(i).ConfigureAwait(false);
        }
    }

    /// <summary>
    /// The counter-example: an ordinary parameter, so the enumeration-time
    /// token is dropped. The compiler warns with CS8425.
    /// </summary>
    public static async IAsyncEnumerable<int> IgnoredAsync(
        Func<int, Task<int>> load,
        int count,
        CancellationToken token = default)
    {
        for (int i = 0; i < count; i++)
        {
            token.ThrowIfCancellationRequested();
            Produced++;
            yield return await load(i).ConfigureAwait(false);
        }
    }

    public static async Task<int> ConsumeAsync(
        IAsyncEnumerable<int> source, CancellationToken token, int stopAfter)
    {
        int seen = 0;
        await foreach (int item in source.WithCancellation(token).ConfigureAwait(false))
        {
            seen++;
            if (seen >= stopAfter) break;
        }

        return seen;
    }
}

