// v3cb05_async_streams / ex4 - disposal ordering, and the abandoned enumerator.

namespace CSharpDojo.V3CB05_AsyncStreams;

public sealed class Resource(List<string> log) : IAsyncDisposable
{
    public ValueTask DisposeAsync()
    {
        log.Add("disposed");
        return default;
    }
}

public static class Cleanup
{
    /// <summary>
    /// An early break resumes this method inside DisposeAsync, so the finally
    /// and then the await using both run - last in, first out.
    /// </summary>
    public static async IAsyncEnumerable<int> ReadAsync(List<string> log, int count)
    {
        await using var resource = new Resource(log);
        log.Add("opened");

        try
        {
            for (int i = 0; i < count; i++)
            {
                await Task.Yield();
                yield return i;
            }
        }
        finally
        {
            log.Add("finally");
        }
    }

    public static async Task<int> TakeAsync(IAsyncEnumerable<int> source, int n)
    {
        int taken = 0;
        await foreach (int item in source.ConfigureAwait(false))
        {
            if (++taken >= n) break;
        }

        return taken;
    }

    /// <summary>
    /// The leak, on purpose: no DisposeAsync means the iterator is never
    /// resumed, so no finally runs and the resource is never released.
    /// </summary>
    public static async Task<int> Abandon(IAsyncEnumerable<int> source)
    {
        IAsyncEnumerator<int> enumerator = source.GetAsyncEnumerator();
        await enumerator.MoveNextAsync().ConfigureAwait(false);
        return enumerator.Current;
    }

    public static string Order(List<string> log) => string.Join(",", log);
}

