// v3cb05_async_streams / ex5 - IAsyncEnumerable and IAsyncEnumerator, by hand.

namespace CSharpDojo.V3CB05_AsyncStreams;

public static class Manual
{
    public static int SyncMoves { get; internal set; }

    public static IAsyncEnumerable<int> Range(int count, Func<int, Task<int>> load) =>
        new Sequence(count, load, CancellationToken.None);

    private sealed class Sequence(int count, Func<int, Task<int>> load, CancellationToken creation)
        : IAsyncEnumerable<int>
    {
        /// <summary>
        /// Link the enumeration-time token with the creation-time one - which
        /// is precisely what [EnumeratorCancellation] generates.
        /// </summary>
        public IAsyncEnumerator<int> GetAsyncEnumerator(CancellationToken token = default) =>
            new Cursor(count, load, CancellationTokenSource.CreateLinkedTokenSource(creation, token));
    }

    private sealed class Cursor(int count, Func<int, Task<int>> load, CancellationTokenSource linked)
        : IAsyncEnumerator<int>
    {
        private int index = -1;

        public int Current { get; private set; }

        public ValueTask<bool> MoveNextAsync()
        {
            linked.Token.ThrowIfCancellationRequested();

            if (index + 1 >= count)
            {
                SyncMoves++;
                return new ValueTask<bool>(false);   // end of sequence: never throw
            }

            return new ValueTask<bool>(AdvanceAsync());
        }

        private async Task<bool> AdvanceAsync()
        {
            index++;
            Current = await load(index).ConfigureAwait(false);
            return true;
        }

        /// <summary>Disposing the linked source is not optional: it is sector 3's leak.</summary>
        public ValueTask DisposeAsync()
        {
            linked.Dispose();
            return default;
        }
    }
}

