// v3cb05_async_streams / ex6 - lazy, cancellable operators.

using System.Runtime.CompilerServices;

namespace CSharpDojo.V3CB05_AsyncStreams;

public static class Operators
{
    public static int Pulled { get; internal set; }

    public static async IAsyncEnumerable<TOut> SelectAwait<TIn, TOut>(
        this IAsyncEnumerable<TIn> source,
        Func<TIn, ValueTask<TOut>> selector,
        [EnumeratorCancellation] CancellationToken token = default)
    {
        await foreach (TIn item in source.WithCancellation(token).ConfigureAwait(false))
            yield return await selector(item).ConfigureAwait(false);
    }

    public static async IAsyncEnumerable<T> Where<T>(
        this IAsyncEnumerable<T> source,
        Func<T, bool> predicate,
        [EnumeratorCancellation] CancellationToken token = default)
    {
        await foreach (T item in source.WithCancellation(token).ConfigureAwait(false))
            if (predicate(item))
                yield return item;
    }

    /// <summary>
    /// The guard before the loop matters: entering an await foreach is itself
    /// a pull, so Take(0) must not start one.
    /// </summary>
    public static async IAsyncEnumerable<T> Take<T>(
        this IAsyncEnumerable<T> source,
        int count,
        [EnumeratorCancellation] CancellationToken token = default)
    {
        if (count <= 0) yield break;

        int taken = 0;
        await foreach (T item in source.WithCancellation(token).ConfigureAwait(false))
        {
            yield return item;
            if (++taken >= count) yield break;
        }
    }
}

