// v3cb05_async_streams / ex7 - batching, with eager validation and a partial tail.

using System.Runtime.CompilerServices;

namespace CSharpDojo.V3CB05_AsyncStreams;

public static class Batching
{
    public static int Writes { get; private set; }

    /// <summary>
    /// Not an iterator: the argument check runs at the call site rather than
    /// at first enumeration.
    /// </summary>
    public static IAsyncEnumerable<T[]> Chunk<T>(
        this IAsyncEnumerable<T> source, int size, CancellationToken token = default)
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(size);
        return ChunkCore(source, size, token);
    }

    private static async IAsyncEnumerable<T[]> ChunkCore<T>(
        IAsyncEnumerable<T> source,
        int size,
        [EnumeratorCancellation] CancellationToken token)
    {
        var buffer = new List<T>(size);

        await foreach (T item in source.WithCancellation(token).ConfigureAwait(false))
        {
            buffer.Add(item);
            if (buffer.Count < size) continue;

            yield return buffer.ToArray();
            buffer.Clear();
        }

        // The partial tail - and nothing at all for an empty source.
        if (buffer.Count > 0) yield return buffer.ToArray();
    }

    public static async Task<int> WriteAllAsync(
        IAsyncEnumerable<int> source, int size, Func<int[], Task> write)
    {
        int calls = 0;
        await foreach (int[] batch in source.Chunk(size).ConfigureAwait(false))
        {
            await write(batch).ConfigureAwait(false);
            calls++;
            Writes++;
        }

        return calls;
    }
}

