// v3cb05_async_streams / ex8 - adapting tasks, channels and sequences into streams.

using System.Runtime.CompilerServices;
using System.Threading.Channels;

namespace CSharpDojo.V3CB05_AsyncStreams;

public static class Adapt
{
    /// <summary>
    /// Yields as tasks finish rather than in list order. Note the O(n^2)
    /// behaviour of repeated WhenAny - fine for a handful, wrong for thousands.
    /// </summary>
    public static async IAsyncEnumerable<int> InCompletionOrderAsync(
        IReadOnlyList<Task<int>> work,
        [EnumeratorCancellation] CancellationToken token = default)
    {
        var pending = new List<Task<int>>(work);

        while (pending.Count > 0)
        {
            token.ThrowIfCancellationRequested();
            Task<int> done = await Task.WhenAny(pending).ConfigureAwait(false);
            pending.Remove(done);                    // reference equality: the same instance
            yield return await done.ConfigureAwait(false);   // rethrows the original exception
        }
    }

    /// <summary>A channel reader already is an async stream.</summary>
    public static IAsyncEnumerable<int> FromChannelAsync(
        ChannelReader<int> reader, CancellationToken token = default) =>
        reader.ReadAllAsync(token);

    /// <summary>
    /// No await anywhere: an in-memory source satisfying a streaming interface.
    /// </summary>
#pragma warning disable CS1998 // deliberately synchronous
    public static async IAsyncEnumerable<int> FromSyncAsync(IEnumerable<int> source)
#pragma warning restore CS1998
    {
        foreach (int item in source) yield return item;
    }

    /// <summary>The boundary where streaming stops and buffering begins.</summary>
    public static async Task<List<int>> ToListAsync(
        IAsyncEnumerable<int> source, CancellationToken token = default)
    {
        var items = new List<int>();
        await foreach (int item in source.WithCancellation(token).ConfigureAwait(false))
            items.Add(item);

        return items;
    }
}

references.Challenge.cs:
// v3cb05_async_streams / challenge - a resilient, disposing, cancellable paged stream.

using System.Runtime.CompilerServices;

namespace CSharpDojo.V3CB05_AsyncStreams;

public readonly record struct Item(int Id, string Value);

public readonly record struct Page(Item[] Items, string? NextCursor);

public static class Challenge
{
    public static int Fetches { get; private set; }

    public static int Retries { get; private set; }

    /// <summary>Not an iterator, so the argument checks run at the call site.</summary>
    public static IAsyncEnumerable<Item> ReadAllAsync(
        Func<string?, CancellationToken, Task<Page>> fetchPage,
        int maxRetriesPerPage,
        IAsyncDisposable client,
        CancellationToken token = default)
    {
        ArgumentNullException.ThrowIfNull(fetchPage);
        ArgumentNullException.ThrowIfNull(client);
        ArgumentOutOfRangeException.ThrowIfNegative(maxRetriesPerPage);
        return Core(fetchPage, maxRetriesPerPage, client, token);
    }

    private static async IAsyncEnumerable<Item> Core(
        Func<string?, CancellationToken, Task<Page>> fetchPage,
        int maxRetriesPerPage,
        IAsyncDisposable client,
        [EnumeratorCancellation] CancellationToken token)
    {
        // Covers all three exits: drained, broken out of, and thrown from.
        await using (client.ConfigureAwait(false))
        {
            string? cursor = null;

            do
            {
                token.ThrowIfCancellationRequested();

                // Fetch the page whole before yielding anything from it, so a
                // retry can never re-deliver an item the consumer already saw.
                Page page = await FetchWithRetryAsync(fetchPage, cursor, maxRetriesPerPage, token)
                    .ConfigureAwait(false);

                foreach (Item item in page.Items) yield return item;

                cursor = page.NextCursor;
            }
            while (cursor is not null);
        }
    }

    /// <summary>
    /// A separate method because C# forbids yield return inside a try that has
    /// a catch - which is a blessing here: fetching and streaming stay apart.
    /// </summary>
    private static async Task<Page> FetchWithRetryAsync(
        Func<string?, CancellationToken, Task<Page>> fetchPage,
        string? cursor,
        int maxRetries,
        CancellationToken token)
    {
        for (int attempt = 0; ; attempt++)
        {
            try
            {
                Fetches++;
                return await fetchPage(cursor, token).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                throw;                                  // never retry an abandoned read
            }
            catch when (attempt < maxRetries)
            {
                Retries++;
            }
        }
    }
}

