// v3cb05_async_streams / review1 - three streaming bugs, diagnosed and repaired.

using System.Runtime.CompilerServices;

namespace CSharpDojo.V3CB05_AsyncStreams;

public static class Audit
{
    public static string Diagnose(string observation) => observation switch
    {
        "the whole source was fetched before the first item" => "eager buffering",
        "cancelling changed nothing" => "missing EnumeratorCancellation",
        "the file stayed open after break" => "no finally in the iterator",
        "the second enumeration returned nothing" => "one-shot source",
        _ => "unknown",
    };

    /// <summary>Yields inside the page loop, so one page is fetched per demand.</summary>
    public static async IAsyncEnumerable<int> RepairedLazy(
        Func<int, Task<int[]>> fetchPage, int pages)
    {
        for (int page = 0; page < pages; page++)
        {
            int[] items = await fetchPage(page).ConfigureAwait(false);
            foreach (int item in items) yield return item;
        }
    }

    /// <summary>The attribute is what lets WithCancellation reach this parameter.</summary>
    public static async IAsyncEnumerable<int> RepairedCancellable(
        Func<int, Task<int>> load,
        int count,
        [EnumeratorCancellation] CancellationToken token = default)
    {
        for (int i = 0; i < count; i++)
        {
            token.ThrowIfCancellationRequested();
            yield return await load(i).ConfigureAwait(false);
        }
    }

    /// <summary>
    /// An early break resumes the iterator inside DisposeAsync, so the finally
    /// runs and the resource is released.
    /// </summary>
    public static async IAsyncEnumerable<int> RepairedDisposal(List<string> log, int count)
    {
        log.Add("opened");
        try
        {
            for (int i = 0; i < count; i++)
            {
                await Task.Yield();
                yield return i;
            }
        }
        finally
        {
            log.Add("released");
        }
    }

    public static string Lesson() =>
        "a stream is a one-shot conversation, driven entirely by the consumer";
}

exercises.hints:
## Hint 1

Two halves, handed to two methods. The producer gets a `ChannelWriter<int>` and
can only write; the consumer gets a `ChannelReader<int>` and can only read.
That separation is not ceremony — it makes "who completes the channel"
unambiguous, because only the writer can.

The consumer is three lines and has no termination logic in it at all.

## Hint 2

```csharp
public static async Task ProduceAsync(ChannelWriter<int> writer, int count)
{
    try
    {
        for (int i = 0; i < count; i++)
            await writer.WriteAsync(i).ConfigureAwait(false);
    }
    finally
    {
        writer.Complete();
    }
}

public static async Task<int> ConsumeAsync(ChannelReader<int> reader)
{
    int total = 0;
    await foreach (int item in reader.ReadAllAsync().ConfigureAwait(false)) total += item;
    return total;
}
```

`RunAsync` starts the producer without awaiting it immediately, consumes, then
awaits both.

## Hint 3

The `finally` is the habit to take away. A producer that throws halfway — a
parse error, a dropped connection — has left items in the channel and a
consumer waiting for more. Without the `finally`, that consumer waits for ever
and your shutdown hangs, and the original exception is buried in an unobserved
task.

The version that also propagates the failure is one line further:

```csharp
catch (Exception ex) { writer.Complete(ex); throw; }
finally { writer.TryComplete(); }
```

`TryComplete` rather than `Complete` in the `finally`, because the `catch` may
already have completed it. Ex7 covers this properly; the habit starts here.

Left to you: whether `RunAsync` should start the producer with `Task.Run` or
simply call it. Calling it is right — it is already async, and wrapping it adds
a pool hop for nothing, which is sector 1's lesson applied to a pipeline.

