// v3cb06_channels_pipelines / ex1 - one producer, one consumer, completion as the terminator.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public static class Simple
{
    /// <summary>
    /// Complete in a finally: a producer that throws must still terminate its
    /// consumer, or the pipeline hangs on shutdown.
    /// </summary>
    public static async Task ProduceAsync(ChannelWriter<int> writer, int count)
    {
        try
        {
            for (int i = 0; i < count; i++)
                await writer.WriteAsync(i).ConfigureAwait(false);
        }
        finally
        {
            writer.Complete();
        }
    }

    /// <summary>
    /// No termination logic at all: the loop ends when the writer completes
    /// and the queue drains.
    /// </summary>
    public static async Task<int> ConsumeAsync(ChannelReader<int> reader)
    {
        int total = 0;
        await foreach (int item in reader.ReadAllAsync().ConfigureAwait(false))
            total += item;

        return total;
    }

    public static async Task<int> RunAsync(int count)
    {
        Channel<int> channel = Channel.CreateUnbounded<int>();

        Task producer = ProduceAsync(channel.Writer, count);
        int total = await ConsumeAsync(channel.Reader).ConfigureAwait(false);
        await producer.ConfigureAwait(false);

        return total;
    }

    public static bool EndedByCompletion(ChannelReader<int> reader) => reader.Completion.IsCompleted;
}

references.Ex2.cs:
// v3cb06_channels_pipelines / ex2 - backpressure, measured exactly.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public static class Pressure
{
    public static int Written { get; private set; }

    public static int Read { get; private set; }

    public static int MaxAhead { get; private set; }

    public static async Task RunAsync(int items, int capacity)
    {
        Written = Read = MaxAhead = 0;

        Channel<int> channel = Channel.CreateBounded<int>(new BoundedChannelOptions(capacity)
        {
            FullMode = BoundedChannelFullMode.Wait,     // the mode that throttles
            SingleReader = true,
            SingleWriter = true,
        });

        Task producer = ProduceAsync(channel.Writer, items);

        await foreach (int _ in channel.Reader.ReadAllAsync().ConfigureAwait(false))
            Read++;

        await producer.ConfigureAwait(false);
    }

    private static async Task ProduceAsync(ChannelWriter<int> writer, int items)
    {
        try
        {
            for (int i = 0; i < items; i++)
            {
                // Does not complete until there is room: this is the whole
                // mechanism, and there is no code of ours in it.
                await writer.WriteAsync(i).ConfigureAwait(false);
                Written++;
                MaxAhead = Math.Max(MaxAhead, Written - Read);
            }
        }
        finally
        {
            writer.Complete();
        }
    }

    /// <summary>
    /// Only Wait throttles the writer. The dropping modes bound memory by
    /// discarding data instead, and never make the producer wait.
    /// </summary>
    public static bool WouldGrowUnbounded(BoundedChannelFullMode mode) =>
        mode != BoundedChannelFullMode.Wait;
}

