// v3cb06_channels_pipelines / ex3 - the wait-then-burst writer protocol.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public static class Protocol
{
    public static int Waits { get; private set; }

    /// <summary>
    /// One WaitToWriteAsync amortised across a burst of TryWrite calls, which
    /// avoids the per-item ValueTask that WriteAsync allocates.
    /// </summary>
    public static async Task<int> PumpAsync(
        ChannelWriter<int> writer, IEnumerator<int> source, CancellationToken token)
    {
        int written = 0;
        bool hasPending = false;
        int pending = 0;

        while (await writer.WaitToWriteAsync(token).ConfigureAwait(false))
        {
            Waits++;

            // Anything pulled from the source but not yet written goes first.
            while (hasPending || source.MoveNext())
            {
                int item = hasPending ? pending : source.Current;

                if (!writer.TryWrite(item))
                {
                    // "Full right now" - not an error. Hold the item and wait.
                    pending = item;
                    hasPending = true;
                    break;
                }

                hasPending = false;
                written++;
            }

            if (!hasPending)
            {
                writer.Complete();       // source exhausted
                return written;
            }
        }

        // WaitToWriteAsync returned false: the channel is closed. Do not complete.
        return written;
    }

    public static string Classify(bool tryWriteResult, bool waitResult) =>
        (tryWriteResult, waitResult) switch
        {
            (true, _) => "burst",
            (false, true) => "full",
            (false, false) => "closed",
        };
}

