// v3cb06_channels_pipelines / ex4 - dropping modes, and counting what they discard.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public static class Sinks
{
    /// <summary>Newest value supersedes the old: a gauge, a price, a position.</summary>
    public static Channel<int> LatestWins(int capacity) =>
        Channel.CreateBounded<int>(new BoundedChannelOptions(capacity)
        {
            FullMode = BoundedChannelFullMode.DropOldest,
        });

    /// <summary>Refuse new work rather than evicting accepted work.</summary>
    public static Channel<int> RejectWhenFull(int capacity) =>
        Channel.CreateBounded<int>(new BoundedChannelOptions(capacity)
        {
            FullMode = BoundedChannelFullMode.DropWrite,
        });

    /// <summary>
    /// Note what this counts: successful TryWrite calls. Under a dropping mode
    /// that is every call, including the ones that discarded data.
    /// </summary>
    public static Task<int> WriteAllAsync(ChannelWriter<int> writer, int count)
    {
        int accepted = 0;
        for (int i = 0; i < count; i++)
            if (writer.TryWrite(i))
                accepted++;

        return Task.FromResult(accepted);
    }

    /// <summary>
    /// TryRead returning false on a live channel means "empty now" - which is
    /// what draining wants, unlike ReadAllAsync which would wait for more.
    /// </summary>
    public static Task<List<int>> DrainAsync(ChannelReader<int> reader)
    {
        var items = new List<int>();
        while (reader.TryRead(out int item)) items.Add(item);
        return Task.FromResult(items);
    }

    /// <summary>The channel will not tell you, so you have to compute it.</summary>
    public static int Dropped(int written, int read) => written - read;
}

references.Ex5.cs:
// v3cb06_channels_pipelines / ex5 - several producers, exactly one completion.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public static class Fan
{
    public static int Completions { get; private set; }

    /// <summary>One producer among several: it must not complete the channel.</summary>
    public static async Task ProduceAsync(
        ChannelWriter<int> writer, int start, int count, CancellationToken token)
    {
        for (int i = 0; i < count; i++)
            await writer.WriteAsync(start + i, token).ConfigureAwait(false);
    }

    public static async Task<int> RunAsync(int producers, int perProducer)
    {
        Completions = 0;
        Channel<int> channel = Channel.CreateBounded<int>(16);

        Task[] running = [.. Enumerable.Range(0, producers)
            .Select(i => ProduceAsync(channel.Writer, i * perProducer, perProducer, CancellationToken.None))];

        // Completion belongs to whoever knows they are all finished.
        Task completer = CompleteWhenDoneAsync(running, channel.Writer);

        int read = 0;
        await foreach (int _ in channel.Reader.ReadAllAsync().ConfigureAwait(false)) read++;

        await completer.ConfigureAwait(false);
        return read;
    }

    private static async Task CompleteWhenDoneAsync(Task[] producers, ChannelWriter<int> writer)
    {
        try
        {
            // WhenAll waits for every producer even after one fails, so we
            // never close the channel under a producer that is still writing.
            await Task.WhenAll(producers).ConfigureAwait(false);
            writer.Complete();
        }
        catch (Exception ex)
        {
            // A dead producer must fault the channel, or the consumer waits
            // for items that will never arrive.
            writer.Complete(ex);
        }

        Completions++;
    }

    public static bool SecondCompleteThrows(ChannelWriter<int> writer)
    {
        writer.Complete();

        try
        {
            writer.Complete();
            return false;
        }
        catch (ChannelClosedException)
        {
            return !writer.TryComplete();     // TryComplete is the safe form
        }
    }
}

references.Ex6.cs:
// v3cb06_channels_pipelines / ex6 - a worker pool over one channel.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public static class Pool
{
    public static int[] PerWorker { get; private set; } = [];

    public static int MaxConcurrent { get; private set; }

    private static int inFlight;

    public static async Task<List<int>> RunAsync(
        int[] input, int workers, Func<int, Task<int>> transform)
    {
        PerWorker = new int[workers];
        MaxConcurrent = 0;
        inFlight = 0;

        Channel<int> work = Channel.CreateBounded<int>(8);
        Channel<int> results = Channel.CreateUnbounded<int>();

        Task producer = FillAsync(work.Writer, input);

        Task[] running = [.. Enumerable.Range(0, workers)
            .Select(id => WorkAsync(id, work.Reader, results.Writer, transform))];

        Task completer = CompleteAfterAsync(running, results.Writer);

        var collected = new List<int>();
        await foreach (int result in results.Reader.ReadAllAsync().ConfigureAwait(false))
            collected.Add(result);

        await producer.ConfigureAwait(false);
        await completer.ConfigureAwait(false);

        // Sorted, so the assertion does not depend on completion order.
        collected.Sort();
        return collected;
    }

    private static async Task FillAsync(ChannelWriter<int> writer, int[] input)
    {
        try
        {
            foreach (int item in input) await writer.WriteAsync(item).ConfigureAwait(false);
        }
        finally
        {
            writer.Complete();
        }
    }

    /// <summary>
    /// The channel guarantees each item goes to exactly one worker; nothing
    /// here coordinates that.
    /// </summary>
    private static async Task WorkAsync(
        int id, ChannelReader<int> reader, ChannelWriter<int> results, Func<int, Task<int>> transform)
    {
        await foreach (int item in reader.ReadAllAsync().ConfigureAwait(false))
        {
            int now = Interlocked.Increment(ref inFlight);
            MaxConcurrent = Math.Max(MaxConcurrent, now);

            try
            {
                int value = await transform(item).ConfigureAwait(false);
                await results.WriteAsync(value).ConfigureAwait(false);
                PerWorker[id]++;
            }
            finally
            {
                Interlocked.Decrement(ref inFlight);
            }
        }
    }

    private static async Task CompleteAfterAsync(Task[] workers, ChannelWriter<int> results)
    {
        try
        {
            await Task.WhenAll(workers).ConfigureAwait(false);
            results.Complete();
        }
        catch (Exception ex)
        {
            results.Complete(ex);
        }
    }
}

