// v3cb06_channels_pipelines / ex7 - faulted completion, and what the reader sees.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public static class Failures
{
    /// <summary>
    /// The queued items survive: a faulted completion drains before it throws.
    /// </summary>
    public static async Task ProduceThenFailAsync(
        ChannelWriter<int> writer, int goodItems, Exception error)
    {
        try
        {
            for (int i = 0; i < goodItems; i++)
                await writer.WriteAsync(i).ConfigureAwait(false);

            writer.TryComplete(error);
        }
        finally
        {
            writer.TryComplete();      // no-op if the line above already completed it
        }
    }

    public static async Task<string> ConsumeAsync(ChannelReader<int> reader)
    {
        int count = 0;

        try
        {
            await foreach (int _ in reader.ReadAllAsync().ConfigureAwait(false)) count++;
            return $"ok: {count}";
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception ex)
        {
            return $"failed: {ex.GetType().Name} after {count}";
        }
    }

    /// <summary>
    /// What a supervisor watches: one task per stage saying how it ended.
    /// Status first, exception second - a non-faulted task's Exception is null.
    /// </summary>
    public static string ObserveCompletion(ChannelReader<int> reader) => reader.Completion switch
    {
        { IsFaulted: true } task => $"faulted:{task.Exception!.InnerException!.GetType().Name}",
        { IsCompletedSuccessfully: true } => "ok",
        _ => "pending",
    };

    /// <summary>
    /// A producer that dies without completing leaves the consumer waiting for
    /// items that will never arrive - which is why completion belongs in a finally.
    /// </summary>
    public static bool HangsWithoutCompletion() => true;
}

