// v3cb06_channels_pipelines / ex8 - a two-stage pipeline with independent bounds.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public static class Stages
{
    public static int Skipped { get; private set; }

    public static int Stage1 { get; private set; }

    public static int Stage2 { get; private set; }

    public static async Task<List<string>> RunAsync(
        IEnumerable<string> input,
        int parseCapacity,
        int formatCapacity,
        CancellationToken token)
    {
        Skipped = Stage1 = Stage2 = 0;

        Channel<int> parsed = Channel.CreateBounded<int>(parseCapacity);
        Channel<string> formatted = Channel.CreateBounded<string>(formatCapacity);

        Task parse = ParseAsync(input, parsed.Writer, token);
        Task format = FormatAsync(parsed.Reader, formatted.Writer, token);

        var results = new List<string>();
        await foreach (string item in formatted.Reader.ReadAllAsync(token).ConfigureAwait(false))
            results.Add(item);

        await parse.ConfigureAwait(false);
        await format.ConfigureAwait(false);
        return results;
    }

    /// <summary>
    /// Completes only its own output. Completion flows downstream; a stage that
    /// completed its input would be signalling upstream, which throws inside a
    /// producer that is still writing.
    /// </summary>
    private static async Task ParseAsync(
        IEnumerable<string> input, ChannelWriter<int> output, CancellationToken token)
    {
        try
        {
            foreach (string entry in input)
            {
                token.ThrowIfCancellationRequested();

                if (!int.TryParse(entry, out int value))
                {
                    Skipped++;
                    continue;
                }

                await output.WriteAsync(value, token).ConfigureAwait(false);
                Stage1++;
            }
        }
        catch (Exception ex)
        {
            output.TryComplete(ex);       // a dead stage must not hang its consumer
            throw;
        }
        finally
        {
            output.TryComplete();
        }
    }

    private static async Task FormatAsync(
        ChannelReader<int> input, ChannelWriter<string> output, CancellationToken token)
    {
        try
        {
            await foreach (int value in input.ReadAllAsync(token).ConfigureAwait(false))
            {
                await output.WriteAsync($"#{value}", token).ConfigureAwait(false);
                Stage2++;
            }
        }
        catch (Exception ex)
        {
            output.TryComplete(ex);
            throw;
        }
        finally
        {
            output.TryComplete();
        }
    }
}

