// v3cb06_channels_pipelines / challenge - an ingest pipeline with per-item failure isolation.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public readonly record struct IngestReport(int Processed, int Failed, int Total);

public static class Ingest
{
    private static int processed;
    private static int failed;

    public static async Task<IngestReport> RunAsync(
        IEnumerable<string> input,
        int capacity,
        int workers,
        Func<string, CancellationToken, Task<int>> handle,
        CancellationToken token)
    {
        processed = 0;
        failed = 0;
        int total = 0;

        Channel<string> work = Channel.CreateBounded<string>(capacity);
        Channel<int> results = Channel.CreateUnbounded<int>();

        Task producer = ProduceAsync(input, work.Writer, count => total = count, token);

        Task[] running = [.. Enumerable.Range(0, workers)
            .Select(_ => WorkAsync(work.Reader, results.Writer, handle, token))];

        Task completer = CompleteResultsAsync(running, results.Writer);

        // Drain the results so the workers are never blocked writing.
        await foreach (int _ in results.Reader.ReadAllAsync(token).ConfigureAwait(false)) { }

        await producer.ConfigureAwait(false);
        await completer.ConfigureAwait(false);

        return new IngestReport(Volatile.Read(ref processed), Volatile.Read(ref failed), total);
    }

    private static async Task ProduceAsync(
        IEnumerable<string> input,
        ChannelWriter<string> writer,
        Action<int> reportTotal,
        CancellationToken token)
    {
        int count = 0;

        try
        {
            foreach (string item in input)
            {
                await writer.WriteAsync(item, token).ConfigureAwait(false);
                count++;
            }
        }
        catch (Exception ex)
        {
            writer.TryComplete(ex);       // workers stop rather than hang
            throw;
        }
        finally
        {
            reportTotal(count);
            writer.TryComplete();
        }
    }

    /// <summary>
    /// The try wraps the handler only, so a bad item is counted and the worker
    /// carries on. Cancellation is deliberately *not* isolated: a cancelled run
    /// must stop, not race through the queue counting failures.
    /// </summary>
    private static async Task WorkAsync(
        ChannelReader<string> reader,
        ChannelWriter<int> results,
        Func<string, CancellationToken, Task<int>> handle,
        CancellationToken token)
    {
        await foreach (string item in reader.ReadAllAsync(token).ConfigureAwait(false))
        {
            try
            {
                int value = await handle(item, token).ConfigureAwait(false);
                await results.WriteAsync(value, token).ConfigureAwait(false);
                Interlocked.Increment(ref processed);
            }
            catch (OperationCanceledException)
            {
                throw;
            }
            catch (Exception)
            {
                Interlocked.Increment(ref failed);
            }
        }
    }

    private static async Task CompleteResultsAsync(Task[] workers, ChannelWriter<int> results)
    {
        try
        {
            await Task.WhenAll(workers).ConfigureAwait(false);
            results.TryComplete();
        }
        catch (Exception ex)
        {
            results.TryComplete(ex);
        }
    }
}

