// v3cb06_channels_pipelines / review1 - four hung pipelines, diagnosed and repaired.

using System.Threading.Channels;

namespace CSharpDojo.V3CB06_Channels;

public static class Triage
{
    public static string Diagnose(string symptom) => symptom switch
    {
        "the consumer never finishes" => "nobody completed the channel",
        "ChannelClosedException on the second producer" => "completed by each producer",
        "memory grows under a slow consumer" => "unbounded channel",
        "reading after the end throws" => "ReadAsync on a completed channel",
        _ => "unknown",
    };

    /// <summary>Completion in a finally: a producer that throws still ends its consumer.</summary>
    public static async Task RepairedCompletion(ChannelWriter<int> writer, int count)
    {
        try
        {
            for (int i = 0; i < count; i++)
                await writer.WriteAsync(i).ConfigureAwait(false);
        }
        finally
        {
            writer.TryComplete();
        }
    }

    /// <summary>
    /// One completion, after every producer, carrying the failure if there was
    /// one. WhenAll rather than sequential awaits, so a failure does not close
    /// the channel under producers that are still writing.
    /// </summary>
    public static async Task RepairedMultiProducer(Task[] producers, ChannelWriter<int> writer)
    {
        try
        {
            await Task.WhenAll(producers).ConfigureAwait(false);
            writer.TryComplete();
        }
        catch (Exception ex)
        {
            writer.TryComplete(ex);
        }
    }

    /// <summary>Wait is the mode that applies backpressure rather than dropping.</summary>
    public static Channel<int> RepairedBound(int capacity) =>
        Channel.CreateBounded<int>(new BoundedChannelOptions(capacity)
        {
            FullMode = BoundedChannelFullMode.Wait,
        });

    /// <summary>
    /// ReadAllAsync ends cleanly at the end of a completed channel; ReadAsync
    /// would throw ChannelClosedException.
    /// </summary>
    public static async Task<int> RepairedDrain(ChannelReader<int> reader)
    {
        int count = 0;
        await foreach (int _ in reader.ReadAllAsync().ConfigureAwait(false)) count++;
        return count;
    }

    public static string Rule() =>
        "bound the channel, complete it once, and let failure travel with it";
}
